import java.util.Scanner;

public class Main {
    static int share(int v) {
        try {
            return {num} / v;
        } catch (ArithmeticException e) {
            System.out.println("接住了：" + e.getMessage());
            return 0;
        } finally {
            System.out.println("收摊");
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            int v = sc.nextInt();
            System.out.println("每只猫分到 " + share(v) + " 条");
        }
    }
}
